  <svg class="logo logo-m {klass}" style={width ? `width:${width}px` : null} viewBox="0 0 956 636" role="img" aria-label={name}>
    <title>{name}</title>
    <use href="#atlas-mark" />
  </svg>
{:else if kind === 'full'}
  <svg class="logo logo-f {klass}" style={width ? `width:${width}px` : null} viewBox="0 0 1365.28 390" role="img" aria-label={name}>
    <title>{name}</title>
    <g transform="translate(0 17.8) scale(0.5)"><use href="#atlas-mark" /></g>
    <use href="#atlas-word" />
    <use href="#atlas-tagline" />
  </svg>
{:else if kind === 'corp'}
  <!-- The corporate lockup, with the horizontal lockup as its narrow twin: the
       tagline stops being legible below the 220px full-lockup minimum, and the
       guidelines answer that case with the horizontal cut rather than a smaller
       corp lockup. Both are <use> references, so the narrow twin costs markup,
       not artwork. -->
  <svg class="logo logo-c {klass}" style={width ? `width:${width}px` : null} viewBox="0 0 1365.28 390" role="img" aria-label={name}>
    <title>{name}</title>
    <g transform="translate(0 17.8) scale(0.5)"><use href="#atlas-mark" /></g>
    <use href="#atlas-word" />
    <use href="#atlas-tagline-corp" />
  </svg>
  <svg class="logo logo-c-narrow {klass}" viewBox="0 0 1365.28 335.8" aria-hidden="true" focusable="false">
    <g transform="translate(0 17.8) scale(0.5)"><use href="#atlas-mark" /></g>
    <use href="#atlas-word" />
  </svg>
{:else}
  <svg class="logo logo-h {klass}" style={width ? `width:${width}px` : null} viewBox="0 0 1365.28 335.8" role="img" aria-label={name}>
    <title>{name}</title>
    <g transform="translate(0 17.8) scale(0.5)"><use href="#atlas-mark" /></g>
    <use href="#atlas-word" />
  </svg>
{/if}

<style>
  .atlas-defs { position: absolute; }
  .logo { display: block; height: auto; }
  /* Clear space is one chevron gap: x = 140 lockup units, which is
     140/1365.28 = 10.25% of the horizontal lockup's rendered width and
     140/1365.28 = 10.25% of the full lockup's. The Avarok wordmark is wider
     than the Atlas one was, so the rendered widths grew to keep the mark the
     same size on the page. */
  .logo-h { width: 152px; margin: calc(152px * 0.1025); }   /* >= 120px */
  .logo-f { width: 244px; margin: calc(244px * 0.1025); }   /* >= 220px */
  .logo-m { width: 30px; }
  /* The corp lockup: clear space is the same chevron gap, 140/1365.28 = 10.25%. */
  .logo-c { width: 244px; margin: calc(244px * 0.1025); }   /* >= 220px */
  .logo-c-narrow { display: none; width: 152px; margin: calc(152px * 0.1025); }
  @media (max-width: 359px) {
    .logo-c { display: none; }
    .logo-c-narrow { display: block; }
  }
  @media (max-width: 520px) {
    .logo-h { width: 132px; margin: calc(132px * 0.1025); }
  }
</style>
